def encode_chat(tok, messages):
    if getattr(tok, 'chat_template', None):
        return tok.apply_chat_template(messages, add_generation_prompt=True, return_tensors='pt', return_dict=True)
    return tok('[INST] ' + '\n\n'.join((m['content'] for m in messages)) + ' [/INST]', return_tensors='pt')

def chat_generate(tok, model, messages, max_new_tokens=200):
    enc = encode_chat(tok, messages).to(model.device)
    with torch.no_grad():
        out = model.generate(**enc, max_new_tokens=max_new_tokens, do_sample=False, pad_token_id=tok.eos_token_id)
    return tok.decode(out[0][enc['input_ids'].shape[-1]:], skip_special_tokens=True).strip()

def chat_generate_batch(tok, model, prompts, max_new_tokens=200, bs=8):
    """Left-padded batched greedy generation (v5 judged one item at a time: ~13 s/item for Prometheus-7B on a T4)."""
    if tok.pad_token is None:
        tok.pad_token = tok.eos_token
    side = tok.padding_side
    tok.padding_side = 'left'
    outs = []

    def render(p):
        m = [{'role': 'user', 'content': p}]
        return tok.apply_chat_template(m, add_generation_prompt=True, tokenize=False) if getattr(tok, 'chat_template', None) else f'[INST] {p} [/INST]'
    try:
        for i in range(0, len(prompts), bs):
            enc = tok([render(p) for p in prompts[i:i + bs]], return_tensors='pt', padding=True, add_special_tokens=False).to(model.device)
            with torch.no_grad():
                out = model.generate(**enc, max_new_tokens=max_new_tokens, do_sample=False, pad_token_id=tok.pad_token_id)
            outs += [tok.decode(o[enc['input_ids'].shape[-1]:], skip_special_tokens=True).strip() for o in out]
    finally:
        tok.padding_side = side
    return outs
