def norm(s):
    s = unicodedata.normalize('NFC', str(s)).lower().strip()
    s = re.sub('[_\\-]+', ' ', s)
    s = re.sub('[^\\w\\sঀ-\u09ff]', ' ', s)
    return re.sub('\\s+', ' ', s).strip()
