_BN_CONS = {'ক': 'k', 'খ': 'kh', 'গ': 'g', 'ঘ': 'gh', 'ঙ': 'ng', 'চ': 'ch', 'ছ': 'chh', 'জ': 'j', 'ঝ': 'jh', 'ঞ': 'n', 'ট': 't', 'ঠ': 'th', 'ড': 'd', 'ঢ': 'dh', 'ণ': 'n', 'ত': 't', 'থ': 'th', 'দ': 'd', 'ধ': 'dh', 'ন': 'n', 'প': 'p', 'ফ': 'ph', 'ব': 'b', 'ভ': 'bh', 'ম': 'm', 'য': 'j', 'র': 'r', 'ল': 'l', 'শ': 'sh', 'ষ': 'sh', 'স': 's', 'হ': 'h', 'ড়': 'r', 'ঢ়': 'rh', 'য়': 'y', 'ৎ': 't'}
_BN_VSIGN = {'া': 'a', 'ি': 'i', 'ী': 'i', 'ু': 'u', 'ূ': 'u', 'ৃ': 'ri', 'ে': 'e', 'ৈ': 'oi', 'ো': 'o', 'ৌ': 'ou'}
_BN_VOW = {'অ': 'o', 'আ': 'a', 'ই': 'i', 'ঈ': 'i', 'উ': 'u', 'ঊ': 'u', 'ঋ': 'ri', 'এ': 'e', 'ঐ': 'oi', 'ও': 'o', 'ঔ': 'ou'}
_BN_MISC = {'ং': 'ng', 'ঃ': 'h', 'ঁ': '', '্': '', '়': ''}

def bn2latin(s):
    s = unicodedata.normalize('NFC', s).replace('ড়', 'ড়').replace('য়', 'য়')
    out = []
    for i, ch in enumerate(s):
        if ch in _BN_CONS:
            out.append(_BN_CONS[ch])
            nxt = s[i + 1] if i + 1 < len(s) else ''
            if nxt and nxt not in _BN_VSIGN and (nxt not in ('্', '়')) and ('ঀ' <= nxt <= '\u09ff'):
                out.append('o')
        elif ch in _BN_VSIGN:
            out.append(_BN_VSIGN[ch])
        elif ch in _BN_VOW:
            out.append(_BN_VOW[ch])
        elif ch in _BN_MISC:
            out.append(_BN_MISC[ch])
        else:
            out.append(ch)
    return ''.join(out)
_PH_RULES = [('chh', 'c'), ('bh', 'b'), ('v', 'b'), ('kh', 'k'), ('gh', 'g'), ('ch', 'c'), ('jh', 'j'), ('th', 't'), ('dh', 'd'), ('ph', 'f'), ('sh', 's'), ('z', 'j'), ('w', 'o'), ('q', 'k'), ('x', 'ks'), ('ee', 'i'), ('oo', 'u'), ('y', 'i'), ('o', 'a'), ('u', 'a'), ('e', 'i')]

def phonetic_key(s):
    s = norm(s)
    if re.search('[ঀ-\u09ff]', s):
        s = bn2latin(s)
    s = re.sub('[^a-z]', '', s)
    for a, b in _PH_RULES:
        s = s.replace(a, b)
    s = re.sub('(.)\\1+', '\\1', s)
    return s[:-1] if len(s) > 4 and s.endswith('h') else s
