HEALTH_CLAIM = re.compile("diabet|blood sugar|pressure|kidney|\\bgout\\b|pcos|thyroid|gluten|celiac|asthma|anemi|safe (for|to)|can (eat|have)|should(n't| not)? (eat|avoid)|suitable|healthy|unhealthy|good for|bad for|ডায়াবেটিস|প্রেশার|খেতে পারে", re.I)

def lexical_support(s, ctx_words):
    """Share of a sentence's content words (len >= 4) that occur in the evidence (5-letter stem match). v6's NLI-only check passed
    'Korola vaji is made by boiling small bamboo shoots' and 'lau is sliced and served cold' — neither 'bamboo' nor 'cold' is in the evidence."""
    w = [t for t in norm(s).split() if len(t) >= 4 and t not in STOP]
    if not w:
        return 1.0
    return sum((t[:5] in ctx_words for t in w)) / len(w)
_VERIFY = {}

def verify(answer, evidence, canon):
    key = (answer, tuple(evidence), canon)
    if key in _VERIFY:
        return _VERIFY[key]
    ctx = ' '.join(evidence)
    evset = set((s.strip() for s in evidence))
    out = {'num_ok': numbers_in(answer) <= numbers_in(ctx), 'entity_ok': mentions_dish(answer, canon), 'unsupported': []}
    sents = split_sents(answer)
    todo = [s for s in sents if s not in evset and numbers_in(s) <= numbers_in(ctx)]
    sup = dict(zip(todo, NLI.support_many(evidence, todo)))
    ctx_words = {t[:5] for t in norm(ctx).split() if len(t) >= 4}
    out['lexical_fail'] = 0
    for s in sents:
        if s in evset:
            continue
        lex = lexical_support(s, ctx_words) >= CFG.get('LEX_MIN', 0.6)
        if not lex:
            out['lexical_fail'] += 1
        if META_TALK.search(s) or HEALTH_CLAIM.search(s) or (not numbers_in(s) <= numbers_in(ctx)) or (sup.get(s, 0) < NLI.min_support) or (not lex):
            out['unsupported'].append(s)
    out['ok'] = out['num_ok'] and out['entity_ok'] and (not out['unsupported'])
    _VERIFY[key] = out
    return out

