_FAKE = ['It usually contains about {n} kcal per serving.', 'It originated in {c} during the {k}th century.', 'It is traditionally cooked with {i}.', 'Each portion has roughly {n} grams of protein.']

def simulated_noisy_answer(q, canon, evidence, strict=False):
    rng = random.Random(int(hashlib.md5((q + canon).encode()).hexdigest()[:8], 16))
    ans = ' '.join(evidence[:2])
    if not strict and rng.random() < 0.35:
        ans += ' ' + rng.choice(_FAKE).format(n=rng.randint(120, 900), c=rng.choice(['Persia', 'Portugal', 'Japan']), k=rng.randint(12, 18), i=rng.choice(['cheese', 'olive oil', 'soy sauce', 'seaweed']))
    return ans

def generate_verified(q, canon, evidence, tr, use_llm=True, do_verify=True):
    gen = extractive_answer
    if use_llm:
        gen = llm_answer if llm_available() else simulated_noisy_answer if SMOKE else extractive_answer
    raw = gen(q, canon, evidence)
    info = {'raw': raw, 'generator': gen.__name__}
    v = verify(raw, evidence, canon)
    info['raw_ok'] = v['ok']
    if not do_verify or v['ok']:
        info['stage'] = 'raw'
        return (raw, info)
    kept = [s for s in split_sents(raw) if s not in v['unsupported']]
    tr.append(f"UNSUPPORTED_CLAIMS {len(v['unsupported'])} (num_ok={v['num_ok']}, entity_ok={v['entity_ok']}) -> drop sentences")
    if kept and verify(' '.join(kept), evidence, canon)['ok']:
        info['stage'] = 'dropped_unsupported'
        return (' '.join(kept), info)
    if gen is not extractive_answer:
        tr.append('REGENERATE strict prompt')
        ans2 = gen(q, canon, evidence, strict=True)
        if verify(ans2, evidence, canon)['ok']:
            info['stage'] = 'strict_regenerate'
            return (ans2, info)
    tr.append('EXTRACTIVE_FALLBACK')
    info['stage'] = 'extractive'
    return (extractive_answer(q, canon, evidence), info)
