def rewrites(q):
    out = []
    for r in (content_query(expand_query(q)), bn2latin(content_query(q))):
        if r and r != q and (r not in out):
            out.append(r)
    return out or [content_query(q) or q]

def plan_features(q):
    """Model-free part: links and rankings (the dense query embeddings must be prefetched)."""
    f = {'q': q, 'links': {}, 'rw_links': {}, 'rank': {}, 'conf': {}, 'rw_rank': []}
    for ph in (True, False):
        ev = []
        f['links'][ph] = (link_entities(q, phonetic=ph, tr=ev), ev)
        f['rw_links'][ph] = []
        for q2 in rewrites(q):
            ev2 = []
            f['rw_links'][ph].append((link_entities(q2, fuzzy_cutoff=80, phonetic=ph, phon_cutoff=82, tr=ev2), ev2))
    for mode in ('base', 'dense', 'hybrid'):
        f['rank'][mode], f['conf'][mode] = RET.search(q, k=8, mode=mode)
    f['rw_rank'] = [RET.search(q2, k=8, mode='hybrid')[0] for q2 in rewrites(q)]
    return f

def probe_of(q):
    """Intent-stripped probe: the dish mention only ("how many calories in X?" -> "x"). The KB holds descriptions, FoodBD holds the
    numbers, so the evaluator should judge whether the passage is about the *dish*, not whether it answers the nutrition request."""
    cq = content_query(q)
    return strip_case(cq) or cq

def link_cands(f):
    return list(dict.fromkeys((c for ph in (True, False) for c in list(f['links'][ph][0]) + [c for e, _ in f['rw_links'][ph] for c in e] if c in DOCS)))

def grader_pairs(f):
    q = f['q']
    pq = probe_of(q)
    top = f['rank']['hybrid'][:5]
    pairs = [(q, c) for c in top] + [(pq, c) for c in top]
    for q2, r in zip(rewrites(q), f['rw_rank']):
        pairs += [(q2, c) for c in r[:5]]
    pairs += [(x, c) for c in link_cands(f) for x in (q, pq)]
    pairs += [(rq, c) for c, rq in repaired_queries(f).items()]
    return pairs

def _span_of(how):
    m = re.match('(?:fuzzy|phonetic):(.+?)->', how)
    return m.group(1) if m else None

def repaired_queries(f):
    """v7: the question with the misspelled span replaced by the dish name ('what is addo?' -> 'what is adda?'). v6 scored only the
    misspelled question, which a cross-encoder cannot match (addo / dewo / bheef were rejected at evaluator 0.02)."""
    out, nq = ({}, norm(f['q']))
    for ph in (True, False):
        for ents in [f['links'][ph][0]] + [e for e, _ in f['rw_links'][ph]]:
            for c, (sc, how) in ents.items():
                sp = _span_of(how)
                if sp and c in DOCS and (sp in nq) and (c not in out):
                    out[c] = nq.replace(sp, norm(DOCS[c]['name'].split('(')[0]))
    return out

def link_coverage(f, c, how):
    """Share of the question's content words explained by the repaired span (near-miss foreign dishes are only partly explained)."""
    sp = _span_of(how)
    ct = content_query(f['q']).split()
    return len(sp.split()) / max(len(ct), 1) if sp else 1.0

def _finish(f):
    q = f['q']
    pq = probe_of(q)
    top = f['rank']['hybrid'][:5]
    f['g0'] = GRADER.score(q, top)
    f['g0p'] = np.maximum(f['g0'], GRADER.score(pq, top))
    f['g_rw'] = [GRADER.score(q2, r[:5]) for q2, r in zip(rewrites(q), f['rw_rank'])]
    f['link_score'] = {c: float(max(GRADER.score(q, [c])[0], GRADER.score(pq, [c])[0])) for c in link_cands(f)}
    ranks = [f['rank']['hybrid']] + f['rw_rank']
    f['link_rank'] = {c: min([r.index(c) + 1 for r in ranks if c in r] or [99]) for c in link_cands(f)}
    f['link_rep'] = {c: float(GRADER.score(rq, [c])[0]) for c, rq in repaired_queries(f).items()}
    return f

def query_features(queries):
    """Batched: one dense-encoding pass and one cross-encoder pass for all queries."""
    allq = list(dict.fromkeys(queries))
    RET.prefetch(allq + [q2 for q in allq for q2 in rewrites(q)])
    feats = {q: plan_features(q) for q in allq}
    GRADER.prefetch([p for f in feats.values() for p in grader_pairs(f)])
    if len(allq) > 20:
        GRADER.save()
    return {q: _finish(f) for q, f in feats.items()}
FEATS = {}

def get_features(q):
    if q not in FEATS:
        FEATS.update(query_features([q]))
    return FEATS[q]

def _verified_links(f, ents, S, TH, tr):
    """A repaired (fuzzy/phonetic) link survives if ANY independent signal agrees: the evaluator, retrieval rank, or a near-exact string match."""
    ents = dict(ents)
    if S['link_verify']:
        for c, (sc, how) in list(ents.items()):
            if how.startswith('alias:') or c not in DOCS:
                continue
            ls, rk = (f['link_score'].get(c, 0.0), f.get('link_rank', {}).get(c, 99))
            lr, cov = (f.get('link_rep', {}).get(c, 0.0), link_coverage(f, c, how))
            if cov < TH.get('cover_min', 0.0):
                ents.pop(c)
                tr.append(f"LINK_REJECTED {how} (explains only {cov:.0%} of the question's content words < {TH['cover_min']:.0%})")
                continue
            if ls >= TH['link_min'] or (rk <= TH.get('link_rank', 0) and ls >= TH.get('link_floor', 0.0)) or sc >= TH.get('link_sim', 101) or (lr >= TH.get('link_rep', 1.01) and sc >= 80):
                if lr >= TH.get('link_rep', 1.01) and ls < TH['link_min']:
                    tr.append(f'LINK_ACCEPTED {how} (repaired question scores {lr:.2f})')
                continue
            ents.pop(c)
            tr.append(f"LINK_REJECTED {how} (evaluator {ls:.3f} < {TH['link_min']:.3f}, retrieval rank {rk} > {TH.get('link_rank', 0)} or evaluator < floor {TH.get('link_floor', 0):.3f}, string sim {sc:.0f} < {TH.get('link_sim', 101)}, repaired question {lr:.2f})")
    return ents

def decide(f, S, TH, tr):
    """Pure decision rule over precomputed features -> (dishes, abstained, kind, ranking)."""
    ph = S['phonetic']
    ranking, conf = (f['rank'][S['retriever']], f['conf'][S['retriever']])
    if S['linker']:
        ents, ev = f['links'][ph]
        tr.extend(ev)
        ents = _verified_links(f, ents, S, TH, tr)
        if ents:
            if S['guard'] and ranking[0] not in ents:
                tr.append(f"ENTITY_GUARD retrieval top '{ranking[0]}' disagrees with linked {list(ents)} -> evidence scoped to linked dishes")
            return (list(ents), False, 'linked', [e for e in ents if e in DOCS] + [c for c in ranking if c not in ents])
    if S['grader']:
        rk, g = (f['rank']['hybrid'][:5], f['g0p'] if S.get('probe') else f['g0'])
        o = np.argsort(-g)
        best, gs = (rk[o[0]], float(g[o[0]]))
        act = lambda s: 'CORRECT' if s >= TH['grader_hi'] else 'INCORRECT' if s < TH['grader_lo'] else 'AMBIGUOUS'
        action = act(gs)
        tr.append(f"EVALUATOR {action} ({gs:.2f} for '{best}')")
        if S['rewrite']:
            for step, q2 in enumerate(rewrites(f['q'])[:CFG['MAX_HEAL_STEPS']]):
                if action == 'CORRECT':
                    break
                if S['linker']:
                    e2, ev2 = f['rw_links'][ph][step]
                    tr.extend(ev2)
                    e2 = _verified_links(f, e2, S, TH, tr)
                    if e2:
                        tr.append(f"REWRITE#{step + 1} '{q2}' -> linked {list(e2)}")
                        return (list(e2), False, 'linked', list(e2) + [c for c in rk if c not in e2])
                r2, g2 = (f['rw_rank'][step][:5], f['g_rw'][step])
                o2 = np.argsort(-g2)
                if len(g2) and float(g2[o2[0]]) > gs:
                    best, gs, g, rk, o = (r2[o2[0]], float(g2[o2[0]]), g2, r2, o2)
                action = act(gs)
                tr.append(f"REWRITE#{step + 1} '{q2}' -> EVALUATOR {action} ({gs:.2f} for '{best}')")
        ranked = [rk[i] for i in o]
        if action == 'INCORRECT':
            tr.append('ABSTAIN (no relevant evidence after healing)')
            return ([], True, 'abstain', ranked)
        if action == 'AMBIGUOUS' and len(g) > 1:
            second, mid = (float(g[o[1]]), (TH['grader_lo'] + TH['grader_hi']) / 2)
            if gs < mid:
                tr.append(f'ABSTAIN ambiguous evidence {gs:.2f} < {mid:.2f}')
                return ([], True, 'abstain', ranked)
            if gs - second < 0.1 and rk[o[1]] != best:
                tr.append(f"CLARIFY '{best}' vs '{rk[o[1]]}' (margin {gs - second:.2f})")
                return ([best, rk[o[1]]], True, 'clarify', ranked)
        return ([best], False, 'retrieved', ranked)
    if S['abstain'] in ('base', 'dense') and conf < TH[S['abstain']]:
        tr.append(f"ABSTAIN similarity {conf:.2f} < {TH[S['abstain']]:.2f}")
        return ([], True, 'abstain', ranking)
    return ([ranking[0]], False, 'retrieved', ranking)
LABEL = {'CHO': 'Carbohydrates (g)', 'Protein': 'Protein (g)', 'Fat': 'Fat (g)', 'Fiber': 'Fiber (g)', 'Calorie': 'Calories (kcal)', 'GL': 'Glycemic load'}
TIER_TXT = {'exact': 'FoodBD plates with exactly these items', 'superset': 'FoodBD plates containing these items plus others', 'model': 'a model over all FoodBD plates (no plate has exactly this combination; rough)'}
IMAGE_HOOK = {}

def answer_query(q, S=FULL, use_llm=True, pool=None, feats=None):
    t0 = time.perf_counter()
    tr = []
    f = feats if feats is not None else get_features(q)
    intent, cols, want_imgs = detect_intent(q)
    pred, abstained, kind, ranking = decide(f, S, S.get('thr', THR), tr)
    res = {'query': q, 'intent': intent, 'entities': [] if abstained else pred, 'abstained': abstained, 'kind': kind, 'ranking': ranking, 'trace': tr, 'nutrition': None, 'gen': None, 'images': None}
    out = []
    if abstained:
        out.append("I could not find this dish in my Bangladeshi-food knowledge base, so I won't guess." if kind == 'abstain' else f"Did you mean {DOCS[pred[0]]['name']} or {DOCS[pred[1]]['name']}? Please tell me which one.")
    elif intent == 'nutrition':
        items, proxies, missing = ([], [], [])
        for c in pred:
            m = FOODBD_MAP.get(c)
            if m is None:
                missing.append(c)
                continue
            items.append(m[0])
            proxies += [f'{c} ~ {m[0]}'] if m[1] == 'proxy' else []
        r = nutrition_for_items(items, pool) if items else None
        res['nutrition'] = r
        if r:
            cols = cols or ['Calorie']
            out.append(f"Nutrition for {' + '.join(items)} per plate, from {TIER_TXT[r['tier']]}" + (f" (n={r['n']})" if r['n'] else '') + f" [confidence: {r['conf']}]: " + '; '.join((f"{LABEL[c]} ~{r['stats'][c][0]:.0f} (range {r['stats'][c][1]:.0f}-{r['stats'][c][2]:.0f})" for c in cols)) + '.')
            if r.get('spread', 0) > 2:
                tr.append(f"WIDE_RANGE spread {r['spread']}x -> confidence lowered")
                out.append('The range is very wide; treat it as a rough guide.')
            if proxies:
                tr.append('PROXY_MAPPING ' + ', '.join(proxies))
                out.append('Approximate: FoodBD has no separate class for ' + ', '.join(proxies) + '.')
        per100 = [c for c in pred if c in NUTR100 and (c in missing or not r or FOODBD_MAP.get(c, ('', ''))[1] == 'proxy')]
        for c in per100:
            d = NUTR100[c]
            tr.append(f"FOODNETBD_PER100G {c} ('{d['name']}', match={d['how']})")
            out.append(f"Per 100 g of {DOCS[c]['name']} (FoodNetBD entry '{d['name']}'): " + ', '.join((f'{k} {d[k]:.0f} kcal' if k == 'energy' else f'{k} {d[k]:.1f} g' for k in ('energy', 'protein', 'fat', 'carbohydrate', 'fibre') if k in d)) + '.')
        rest = [c for c in missing or ([] if r else pred) if c not in per100]
        if rest:
            tr.append(f'NO_NUTRITION_DATA {rest} -> description instead of invented numbers')
            out.append('I have no nutrition data for ' + ', '.join((DOCS[c]['name'] if c in DOCS else c for c in rest)) + ", so I won't give numbers.")
            for c in rest[:2]:
                if c in DOCS:
                    out.append(DOC_TEXT[c])
    elif intent == 'images' and 'search' in IMAGE_HOOK:
        res['images'] = {'pictures': [], 'verified': 0, 'per_dish': {}}
        k_each = 5 if len(pred) == 1 else 3
        for c in pred[:3]:
            s = IMAGE_HOOK['search'](c, k=k_each, tr=tr)
            n = s['verified']
            nm = DOCS[c]['name'] if c in DOCS else c
            res['images']['pictures'] += s['pictures']
            res['images']['verified'] += n
            res['images']['per_dish'][c] = n
            ident = (split_sents(DOC_TEXT[c]) or [nm])[0] if c in DOCS else c
            out.append(ident + (f' Here are {n} verified pictures of {nm}.' if n else f' I have no verified pictures of {nm} in my image gallery, so I am not showing unrelated photos.'))
    else:
        conds_q = conditions_in(q)
        recipe_q = bool(re.search(ASPECTS[1][0], q, re.I))
        for c in pred[:2]:
            if c in DOCS and recipe_q:
                sents = split_sents(DOC_TEXT[c])
                facts = [s for s in sents if re.search('^Ingredients:|Cooking method:', s)]
                tr.append(f'RECIPE_QUESTION -> extractive ({len(facts)} ingredient/method lines in KB, no generation)')
                out.append(' '.join(sents[:1] + facts) + (' ' if facts else ' ') + f"My knowledge base has no step-by-step recipe for {DOCS[c]['name']}, so I won't invent one.")
                continue
            if c in DOCS:
                ev = refine_evidence(c, q)
                if conds_q:
                    tr.append('DIET_QUESTION -> description is extractive; suitability comes only from FoodNetBD tags')
                ans, ginfo = generate_verified(q, c, ev, tr, use_llm=use_llm and (not conds_q), do_verify=S['verify'])
                if res['gen'] is None:
                    res['gen'] = ginfo | {'evidence': ev, 'canon': c, 'answer': ans}
                out.append(ans)
            else:
                w = wiki_summary(c)
                tr.append(f'NO_KB_DOC({c}) -> ' + ('Wikipedia fallback' if w else 'no source, abstain on description'))
                out.append(w if w else f"I know '{c}' only as a FoodBD plate item and have no reliable description.")
        if want_imgs and 'search' in IMAGE_HOOK and pred:
            res['images'] = IMAGE_HOOK['search'](pred[0], k=5, tr=tr)
    conds = conditions_in(q) if not abstained else []
    if conds:
        res['health'] = {}
        for c in pred[:2]:
            nm = DOCS[c]['name'] if c in DOCS else c
            tags = HEALTH.get(c, {}).get('tags', {})
            for k in conds:
                if k in tags:
                    res['health'][c, k] = tags[k]
                    tr.append(f"DIET_TAG {c}/{k}={tags[k]} (FoodNetBD '{HEALTH[c]['name']}', match={HEALTH[c]['how']})")
                    out.append(f"FoodNetBD tags {nm} as '{tags[k]}' for {COND_NAME[k]}.")
                else:
                    tr.append(f'NO_DIET_TAG {c}/{k} -> no claim')
                    out.append(f"I have no FoodNetBD diet tag for {nm} and {COND_NAME[k]}, so I won't say whether it is suitable.")
        out.append('(Diet tags are general guidance from the FoodNetBD dataset, not medical advice; ask your doctor or dietitian.)')
    res['answer'] = '\n'.join(out)
    res['latency_ms'] = 1000 * (time.perf_counter() - t0)
    return res

def show(res):
    print('Q:', res['query'])
    print(res['answer'])
    print('  entities:', res['entities'], '| kind:', res['kind'])
    print('  healing trace:', res['trace'] or 'none needed')
from PIL import Image, ImageDraw

def to_canon(label):
    e = link_entities(str(label).replace('_', ' '))
    return max(e, key=lambda k: e[k][0]) if e else norm(label)
_LABEL_MAP = {}

def map_label(label):
    """Classifier label -> KB dish (v7). tanziro's 841 labels mix Bangla folder names ('কাচা_গোল্লা') and English; v6 mapped them with the
    query linker only, and recogniser A scored 4.6 % on FoodBD crops. Order: DeshiFoodBD Bangla names, exact alias, Bangla spelling fold,
    linker, fuzzy alias on the transliteration. Unmapped labels return None (their probability is not credited to any dish)."""
    if label in _LABEL_MAP:
        return _LABEL_MAP[label]
    l = str(label).replace('_', ' ').strip()
    n = norm(l)
    out = None
    if l in DESHI_BN:
        out = DESHI_BN[l]
    elif n in ALIAS2CANON:
        out = ALIAS2CANON[n]
    elif not n.isascii() and bn_fold(n) in ALIAS_FOLD:
        out = ALIAS_FOLD[bn_fold(n)]
    else:
        e = link_entities(l, phonetic=False)
        if e:
            out = max(e, key=lambda k: e[k][0])
        else:
            m = best_match(n if n.isascii() else bn2latin(n), ALIAS_LIST, 88)
            out = ALIAS2CANON[m[0]] if m else None
    _LABEL_MAP[label] = out if out is None or out in DOCS else None
    return _LABEL_MAP[label]
IMG_EXTS = ('.jpg', '.jpeg', '.png', '.webp')
IMG_SPLITS = {'gallery': [], 'calib': [], 'test': []}
OOD = '__ood__'
CLF, CLIP = (None, None)

def _feat(o):
    if torch.is_tensor(o):
        return o
    po = getattr(o, 'pooler_output', None)
    return po if po is not None else o[0]

def _open(p, size=448):
    """Open an image; 'path#x0,y0,x1,y1' (normalised box) returns that crop (FoodBD polygon instances)."""
    crop, pid = (None, None)
    if '#' in p:
        parts = p.split('#')
        p = parts[0]
        crop = [float(v) for v in parts[1].split(',')]
        pid = int(parts[2]) if len(parts) > 2 else None
    im = Image.open(p)
    if im.format == 'JPEG':
        im.draft('RGB', (size * (2 if crop else 1), size * (2 if crop else 1)))
    im = im.convert('RGB')
    if crop:
        W, H = im.size
        x0, y0, x1, y1 = crop
        m = 0.04
        box = (int(max(0, x0 - m) * W), int(max(0, y0 - m) * H), int(min(1, x1 + m) * W), int(min(1, y1 + m) * H))
        if pid is not None and CFG.get('MASK_CROPS', True) and ('poly' in INST.columns):
            mask = Image.new('L', im.size, 0)
            ImageDraw.Draw(mask).polygon([(float(x) * W, float(y) * H) for x, y in INST.at[pid, 'poly']], fill=255)
            im = Image.composite(im, Image.new('RGB', im.size, (128, 128, 128)), mask)
        im = im.crop(box)
    im.thumbnail((size * 2, size * 2))
    return im
from concurrent.futures import ThreadPoolExecutor
_POOL = ThreadPoolExecutor(8)

def open_many(items):
    return list(_POOL.map(lambda p: _open(p) if isinstance(p, str) else p, items))

def clip_img(items, bs=64):
    m, proc = CLIP
    outs = []
    for i in range(0, len(items), bs):
        ims = open_many(items[i:i + bs])
        with torch.no_grad(), amp():
            f = _feat(m.get_image_features(**proc(images=ims, return_tensors='pt').to(m.device)))
        outs.append(torch.nn.functional.normalize(f.float(), dim=-1).cpu().numpy())
    return np.concatenate(outs)

def clip_txt(texts, bs=256):
    m, proc = CLIP
    outs = []
    for i in range(0, len(texts), bs):
        with torch.no_grad(), amp():
            f = _feat(m.get_text_features(**proc(text=texts[i:i + bs], return_tensors='pt', padding=True, truncation=True, max_length=77).to(m.device)))
        outs.append(torch.nn.functional.normalize(f.float(), dim=-1).cpu().numpy())
    return np.concatenate(outs)

def _pix(p):
    return np.asarray(_open(p).resize((8, 8)), dtype=float).ravel() / 255

def _hist(p):
    hsv = np.asarray(_open(p).convert('HSV').resize((32, 32))).reshape(-1, 3)
    h, _ = np.histogramdd(hsv, bins=(8, 4, 4), range=((0, 256), (0, 256), (0, 256)))
    h = h.ravel()
    return h / np.linalg.norm(h)

def img_embed(paths):
    if CLIP is not None:
        return clip_img(paths)
    X = np.array([np.r_[_hist(p), 0.5 * _pix(p)] for p in paths])
    return X / np.linalg.norm(X, axis=1, keepdims=True)
_IMG = {}

def precompute_images(paths, bs=32):
    """Recogniser A, recogniser B, embedding, kNN — once per image, batched."""
    new = [p for p in dict.fromkeys(paths) if p not in _IMG]
    for i in range(0, len(new), 256):
        chunk = new[i:i + 256]
        _t0 = time.perf_counter()
        E = img_embed(chunk)
        if CLF is not None:
            outs = CLF(open_many(chunk), batch_size=bs)
            PA = []
            for o in outs:
                d = {}
                for r in o:
                    c = map_label(r['label'])
                    if c:
                        d[c] = d.get(c, 0) + float(r['score'])
                d = d or {'_unmapped': 1.0}
                PA.append(d)
        else:
            PA = [dict(zip(_rA.classes_, pr)) for pr in _rA.predict_proba(np.array([_pix(p) for p in chunk]))]
        PB = PROBE.predict_proba(E)
        for p, e, pa, pr in zip(chunk, E, PA, PB):
            idx = np.argsort(-pr)[:5]
            pb = {str(PROBE.classes_[j]): float(pr[j]) for j in idx}
            sims = G_EMB @ e
            nn = np.argsort(-sims)
            nn = [j for j in nn[:11] if G_PATHS[j] != p][:10]
            pk = collections.Counter()
            for j in nn:
                pk[G_LAB[j]] += max(float(sims[j]), 0)
            tot = sum(pk.values()) or 1.0
            _IMG[p] = {'emb': e, 'A': pa, 'B': pb, 'K': {c: v / tot for c, v in pk.items()}}
        for p in chunk:
            _IMG[p]['ms'] = 1000 * (time.perf_counter() - _t0) / len(chunk)
IMG_TAU, IMG_CAL = (0.5, (1.0, 0.0))
W_FUSE, W_HEAL, IMG_HEAL = ((0.5, 0.5), (1 / 3, 1 / 3, 1 / 3), True)

def _logit(p):
    p = np.clip(p, 0.0001, 1 - 0.0001)
    return np.log(p / (1 - p))

def calibrated(conf):
    a, b = IMG_CAL
    return float(1 / (1 + np.exp(-(a * _logit(conf) + b))))

def _combine(dicts, w):
    f = collections.Counter()
    for d, wi in zip(dicts, w):
        for c, v in d.items():
            if c != '_unmapped':
                f[c] += wi * v
    return f
CAT_TAU = None

def dish_category(c):
    cat = norm(DOCS[c].get('category', '')) if c in DOCS else ''
    return cat or None

def category_vote(fused):
    """Sum the fused dish probabilities by KB category ('meat curry', 'vegetable', 'sweet' ...)."""
    cv = collections.Counter()
    members = collections.defaultdict(list)
    for c, v in fused.items():
        k = dish_category(c)
        if k:
            cv[k] += v
            members[k].append((c, v))
    if not cv:
        return None
    k, s = cv.most_common(1)[0]
    tot = sum(fused.values()) or 1.0
    return (k, s / tot, [c for c, _ in sorted(members[k], key=lambda x: -x[1])[:3]])

def classify_image(path, heal=None, agree_conf=0.5, w_fuse=None, w_heal=None):
    heal = IMG_HEAL if heal is None else heal
    precompute_images([path])
    d = _IMG[path]
    tr = []
    pa, pb = (d['A'], d['B'])
    fused = _combine((pa, pb), w_fuse or W_FUSE)
    top_a, top_b = (max(pa, key=pa.get), max(pb, key=pb.get))
    best, conf = fused.most_common(1)[0]
    if heal and (top_a != top_b or conf < agree_conf):
        pk = d['K']
        tr.append(f'RECOGNISERS_DISAGREE (A={top_a}, B={top_b}, fused={conf:.2f}) -> add gallery kNN vote')
        fused = _combine((pa, pb, pk), w_heal or W_HEAL)
        best, conf = fused.most_common(1)[0]
        tr.append(f'HEALED -> {best} ({conf:.2f})')
    raw_conf = conf
    conf = calibrated(conf)
    uncertain = conf < IMG_TAU
    cat = None
    if uncertain:
        tr.append(f'IMAGE_UNCERTAIN {conf:.2f} < tau {IMG_TAU:.2f} -> do not name a dish')
        cv = category_vote(fused)
        if cv and CAT_TAU is not None and (cv[1] >= CAT_TAU):
            cat = cv
            tr.append(f"CATEGORY_BACKOFF '{cv[0]}' ({cv[1]:.2f} >= {CAT_TAU:.2f}) -> name the kind of dish, not the dish")
    return {'top': str(best), 'conf': float(conf), 'ranked': [(str(c), float(v)) for c, v in fused.most_common(5)], 'A': top_a, 'B': top_b, 'uncertain': uncertain, 'category': cat, 'trace': tr, 'emb': d['emb'], 'raw_conf': float(raw_conf)}

def calibrate_tau(results, labels, target):
    conf = np.array([r['conf'] for r in results])
    ok = np.array([r['top'] == l for r, l in zip(results, labels)])
    for t in np.unique(np.round(conf, 3)):
        m = conf >= t
        if m.sum() >= 10 and ok[m].mean() >= target:
            return float(t)
    return float(conf.max())

def image_search(canon, k=5, tr=None, verify_labels=True):
    if CLIP is not None:
        q = clip_txt([f"a photo of {(DOCS[canon]['name'] if canon in DOCS else canon)}, a Bangladeshi food"])[0]
        order = np.argsort(-(P_EMB @ q))
    else:
        cen = P_EMB[P_LAB == canon].mean(0) if (P_LAB == canon).any() else P_EMB.mean(0)
        order = np.argsort(-(P_EMB @ cen))
    raw = [(P_PATHS[i], str(P_LAB[i])) for i in order[:k]]
    if not verify_labels:
        return {'pictures': raw, 'raw': raw, 'verified': None}
    ok = [(P_PATHS[i], str(P_LAB[i])) for i in order if P_LAB[i] == canon][:k]
    if tr is not None:
        bad = sum((l != canon for _, l in raw))
        if bad:
            tr.append(f"PICTURE_LABEL_MISMATCH {bad}/{k} raw results not '{canon}' -> filtered")
        if len(ok) < k:
            tr.append(f"ONLY_{len(ok)}_VERIFIED_PICTURES for '{canon}' (gallery has no more)")
    return {'pictures': ok, 'raw': raw, 'verified': len(ok)}
PLATE_DET, ALL_EMB_BY_STEM, ROUTER_T = (None, {}, 0.5)

def is_plate_photo(path):
    if PLATE_DET is None:
        return 0.0
    precompute_images([path])
    return float(ROUTER.predict_proba(_IMG[path]['emb'][None])[0, 1])

def detect_plate_items(path):
    """-> [(FoodBD item, KB dish, probability)] above the per-class thresholds, most likely first."""
    if PLATE_DET is None:
        return []
    e = img_embed([path]) if path not in _IMG else _IMG[path]['emb'][None]
    pr = _det_proba(e)[0]
    it2c = {it: c for c, (it, how) in FOODBD_MAP.items() if how == 'exact' and c in DOCS}
    return [(DET_CLASSES[j], it2c.get(DET_CLASSES[j], norm(DET_CLASSES[j])), float(pr[j])) for j in np.argsort(-pr) if pr[j] >= DET_THR[j]]
PLATE = None
PLATE_COND = None

def plate_estimate(path):
    if PLATE is None:
        return None
    e = clip_img([path])
    p = _e2e.predict(e)[0]
    q, cond = (_Qimg, None)
    if PLATE_COND and PLATE_COND['use_predicted']:
        cond = str(_cclf.predict(e)[0])
        q = PLATE_COND['Q'][cond]
    out = {c: (float(v), float(max(0, v - qq)), float(v + qq)) for c, v, qq in zip(NUTR, p, q)}
    out['_cond'] = (PLATE_COND['column'], cond) if cond else None
    return out

def show_images(pairs, title=''):
    import matplotlib.pyplot as plt
    if not pairs:
        print('(no pictures)')
        return
    fig, axs = plt.subplots(1, len(pairs), figsize=(2.4 * len(pairs), 2.6))
    for ax, (p, l) in zip(np.atleast_1d(axs), pairs):
        ax.imshow(_open(p))
        ax.set_title(l, fontsize=8)
        ax.axis('off')
    fig.suptitle(title, fontsize=9)
    plt.tight_layout()
    plt.show()

def multimodal_answer(question=None, image=None, plate=False):
    rep = {'trace': []}
    q = question or 'what is this dish?'
    plate = plate or (PLATE is not None and detect_intent(q)[0] == 'nutrition')
    if image and plate:
        est = plate_estimate(image)
        if est:
            rep['plate_estimate'] = est
            rep['trace'].append('PLATE_PHOTO -> CLIP regression estimate with conformal 80% interval')
            if est['_cond']:
                rep['trace'].append(f"CONDITION {est['_cond'][0]}={est['_cond'][1]} (predicted from the photo) -> condition-specific interval")
    if image:
        c = classify_image(image)
        rep['trace'] += c['trace']
        rep['image_candidates'] = [(d, round(s, 2)) for d, s in c['ranked'][:3]]
        items = detect_plate_items(image)
        if items:
            rep['plate_items'] = [(it, round(p, 2)) for it, _, p in items]
        pp = is_plate_photo(image)
        rep['plate_prob'] = round(pp, 2)
        if not link_entities(q) and len(items) >= 2 and (pp >= ROUTER_T):
            rep['trace'].append(f"MEAL_PLATE (router p={pp:.2f}) -> PLATE_ITEMS_DETECTED {rep['plate_items']} -> answer for the whole plate, not one dish label")
            dishes = list(dict.fromkeys((cn for _, cn, _ in items if cn in DOCS)))
            names_ = ', '.join((f"{DOCS[cn]['name']} ({p:.2f})" if cn in DOCS else f'{it} ({p:.2f})' for it, cn, p in items))
            if detect_intent(q)[0] == 'nutrition' and dishes:
                res = answer_query(q + ' ' + ' and '.join((DOCS[d]['name'] for d in dishes[:4])))
                rep['trace'] += res['trace']
                res['answer'] = f'This looks like a meal plate with: {names_}.\n' + res['answer']
            else:
                res = {'answer': f'This looks like a meal plate with: {names_}. ' + ' '.join(((split_sents(DOC_TEXT[d]) or [DOCS[d]['name']])[0] for d in dishes[:4])), 'entities': dishes, 'trace': []}
            rep['text'] = res
            if rep.get('plate_estimate'):
                e = rep['plate_estimate']
                cols = detect_intent(q)[1] or ['Calorie']
                res['answer'] += '\nWhole-plate estimate from the photo (CLIP regression on FoodBD, 80% interval): ' + '; '.join((f'{LABEL[c_]} ~{e[c_][0]:.0f} ({e[c_][1]:.0f}-{e[c_][2]:.0f})' for c_ in cols)) + '.'
            sims = P_EMB @ c['emb']
            rep['similar'] = [(P_PATHS[i], P_LAB[i]) for i in np.argsort(-sims)[:5]]
            return rep
        if not link_entities(q):
            if c['uncertain']:
                if c.get('category'):
                    k, s, mem = c['category']
                    msg = f"I'm not sure of the exact dish, but it looks like a {k} dish (category confidence {s:.2f}) - most likely " + ', '.join((DOCS[m]['name'] for m in mem if m in DOCS)) + ". Tell me the name and I'll look it up. Here are similar pictures."
                else:
                    msg = f"I'm not confident which dish this is (best {c['top']} at {c['conf']:.2f} < {IMG_TAU:.2f}), so I won't guess. Candidates: {rep['image_candidates']}. Here are the most similar pictures I have."
                rep['text'] = {'answer': msg, 'trace': []}
                if rep.get('plate_estimate'):
                    e = rep['plate_estimate']
                    cols = detect_intent(q)[1] or ['Calorie']
                    rep['text']['answer'] += '\nWhole-plate estimate from the photo (CLIP regression on FoodBD, 80% interval): ' + '; '.join((f'{LABEL[c_]} ~{e[c_][0]:.0f} ({e[c_][1]:.0f}-{e[c_][2]:.0f})' for c_ in cols)) + '.'
                sims = P_EMB @ c['emb']
                rep['similar'] = [(P_PATHS[i], P_LAB[i]) for i in np.argsort(-sims)[:5]]
                return rep
            q = f"{q} {c['top']}"
            rep['trace'].append(f"Question had no dish -> using image prediction '{c['top']}'")
    res = answer_query(q)
    rep['text'] = res
    rep['trace'] += res['trace']
    if rep.get('plate_estimate'):
        e = rep['plate_estimate']
        cols = detect_intent(q)[1] or ['Calorie']
        res['answer'] += '\nWhole-plate estimate from the photo (CLIP regression on FoodBD, 80% interval): ' + '; '.join((f'{LABEL[c]} ~{e[c][0]:.0f} ({e[c][1]:.0f}-{e[c][2]:.0f})' for c in cols)) + '.'
    if res.get('images'):
        rep['similar'] = res['images']['pictures']
    elif image:
        sims = P_EMB @ _IMG[image]['emb']
        rep['similar'] = [(P_PATHS[i], P_LAB[i]) for i in np.argsort(-sims)[:5]]
    return rep
